async function navigate(next){if(next==='collections'){collectibleView='collection';next='collectibles';}if(next==='progression'){collectibleView='mastery';progressionKind='mastery';next='collectibles';}page=next;render();window.scrollTo({top:0,behavior:'instant'});if(isCatalogPage())await loadCatalog();if(page==='workshop')await loadExpansions();if(isProgressionPage())await loadProgression();if(page==='farming')await loadFarming();if(helperKind())await loadHelpers(helperKind());}
async function loadCatalog(){
  const request=++catalogRequest;
  const untabbed=page==='untabbed';
  const params=new URLSearchParams({q:catalogQuery,type:catalogType,subtype:catalogSubtype,artwork:catalogArtwork,sort:catalogSort,page:String(catalogPage),limit:'20',grantable:grantableOnly&&!untabbed?'1':'0'});
  if(untabbed){params.set('origin',untabbedOrigin);params.set('gift',untabbedShowRefused?'all':'giftable');}
  else{
    if(page==='archive'&&catalogCollection)params.set('collection',catalogCollection);
    if(historyYear)params.set('year',historyYear);if(historyAcquisition)params.set('acquisition',historyAcquisition);
    if(seasonalFilter)params.set('seasonal',seasonalFilter);
    if(calendarDate)params.set('calendarDate',calendarDate);
  }
  if(favoritesOnly)params.set('names',[...favorites].join(','));
  const grid=document.getElementById('catalog-grid');if(grid)grid.style.opacity='.45';
  try{const result=await api((untabbed?'/api/untabbed?':'/api/catalog?')+params);if(request!==catalogRequest)return;catalog=result;catalogPage=result.page||1;if(isCatalogPage())updateMarket();}catch(error){errorToast(error);if(grid)grid.style.opacity='1';}
}
function updateMarket(){const content=document.getElementById('page-content');const focused=document.activeElement?.id==='catalog-search',pos=document.activeElement?.selectionStart;content.innerHTML=page==='archive'?archiveMarket():page==='untabbed'?untabbedMarket():market();if(focused){const input=document.getElementById('catalog-search');input.focus();input.setSelectionRange(pos,pos);}}
async function loadExpansions(){try{const result=await api('/api/catalog?type=expand_farm&limit=200');let items=result.items||[];if(!items.length){const more=await api('/api/catalog?q=expand&limit=200');items=more.items||[];}const sizes=(result.expansionSizes||[...new Set(items.filter(i=>i.subtype==='expand_farm').map(i=>Number(i.squares)))]).filter(x=>x>Math.max(Number(save().world?.sizeX),Number(save().world?.sizeY))).sort((a,b)=>a-b);const select=document.getElementById('farm-size');if(select)select.innerHTML=sizes.length?sizes.map(x=>`<option value="${x}">${x} × ${x}</option>`).join(''):'<option value="">No larger supported size</option>';}catch(error){errorToast(error);}}
function showModal(markup){modalReturnFocus=document.activeElement;overlay.innerHTML=`<div class="modal-shade">${modeMarkup(markup)}</div>`;document.body.style.overflow='hidden';app.inert=true;overlay.querySelector('button,input,select')?.focus();}
function closeModal(){overlay.innerHTML='';document.body.style.overflow='';app.inert=false;lastPreview=null;modalReturnFocus?.focus();}
function findKnownItem(value){return (catalog.items||[]).find(item=>item.name===value||item.code===value)||[...cropItems.values()].find(item=>item.name===value||item.code===value);}
function readablePath(path){
  const parts=String(path||'').split('/').slice(1).map(value=>value.replace(/~1/g,'/').replace(/~0/g,'~')),field=parts.at(-1);
  const labels={gold:'Farm Coins',cash:'Farm Cash',xp:'Experience',level:'Farmer level',energy:'Fuel',turboChargers:'Turbo charges',sizeX:'Farm width',sizeY:'Farm depth',isJumbo:'Fertilized crop',plantTime:'Harvest timer',state:'Crop condition',itemName:'Crop',enabled:'Peaceful mode'};
  if(parts.includes('collectionCounters')){const code=parts[parts.indexOf('collectionCounters')+1],item=helperData.collection?.items?.flatMap(row=>row.items||[]).find(item=>item.code===code||item.name===code);return item?.displayName?item.displayName+' collected':'Collectibles held';}
  if(parts.includes('questState')){const index=parts.indexOf('active'),row=helperData.quest?.items?.find(row=>row.name===parts[index+1]||row.id===parts[index+1]),taskIndex=Number(parts[parts.indexOf('progress')+1]);return row?.tasks?.[taskIndex]?.displayName||'Quest task progress';}
  if(parts.includes('masteryCounters'))return 'Mastery points';if(parts.includes('mastery'))return 'Mastery stars';if(parts.includes('achCounters'))return 'Achievement points';if(parts.includes('achievements'))return 'Ribbons earned';
  if(parts.includes('storageData')||parts.includes('storage'))return 'Stored gifts';
  if(labels[field])return labels[field];
  if(parts.includes('objectsArray'))return 'Farm item';
  return 'Farm update';
}
function changeValue(value){if(value===undefined||value===null)return '—';if(typeof value==='number')return number(value);if(typeof value==='boolean')return value?'On':'Off';if(typeof value==='object')return Array.isArray(value)?`${value.length} items`:'Updated';return {planted:'Growing',grown:'Ready',withered:'Withered',plowed:'Open soil',empty:'Empty'}[value]||'Updated';}
function previewValue(change,value){const field=String(change.path||'').split('/').at(-1);if(['gold','cash'].includes(field)&&typeof value==='number')return currencyAmount(value,field==='cash'?'cash':'coins');if(field==='plantTime'&&typeof value==='number')return esc(shortDate(value));if(field==='itemName'&&value){const item=findKnownItem(value);return esc(item?displayName(item):'New crop');}return esc(changeValue(value));}
function previewChanges(result){return (result.changes||[]).slice(0,80).map(change=>`<div class="change"><span class="path">${esc(readablePath(change.path))}</span><span class="before">${previewValue(change,change.before)}</span><span class="after">→ ${previewValue(change,change.after)}</span></div>`).join('');}
async function preview(operation){if(busy)return;const farmId=state.farm.id,revision=state.farm.revision;busy=true;try{const result=await api('/api/preview',{operation,farmId,revision});if(farmId!==state?.farm?.id||revision!==state?.farm?.revision)return;lastPreview=result;showModal(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="preview-heading"><header class="modal-head"><div><div class="eyebrow">A little look ahead</div><h2 id="preview-heading">Before the magic happens</h2><p>${esc(state.farm.name)} · copied save only</p></div><button class="close" data-action="close-modal" aria-label="Close preview">×</button></header><div class="modal-body"><div class="preview-summary">${playerText(result.summary)}</div>${result.gift?giftCard(result.gift):''}${(result.warnings||[]).map(w=>`<div class="warning">${playerText(w)}</div>`).join('')}<div class="change-list">${previewChanges(result)||'<div class="empty small">This copy already has those values.</div>'}</div>${result.changes?.length>80?`<p class="helper-line">${result.changes.length-80} additional fields will change.</p>`:''}</div><footer class="modal-footer"><p>A snapshot is saved before applying.</p><div class="modal-buttons">${actionButton('Keep it as it is','close-modal','')}${actionButton('Apply to this copy','apply-preview','primary',!(result.changes||[]).length?'disabled':'')}</div></footer></section>`);}catch(error){errorToast(error);}finally{busy=false;}}
async function applyPreview(){
  if(!lastPreview||busy)return;busy=true;
  const preview=lastPreview,button=overlay.querySelector('[data-action="apply-preview"]');
  if(button){button.disabled=true;button.textContent=isLive()?'Saving your farm…':'Saving your copy…';}
  try{
    acceptSavedState(await api('/api/apply',{token:preview.token,farmId:state.farm.id,revision:state.farm.revision}));invalidateFarmTools();
    closeModal();await loadCropItems();if(isProgressionPage())await loadProgression(false);if(page==='farming')await loadFarming(false);if(helperKind())await loadHelpers(helperKind(),false);render();
    if(isCatalogPage())await loadCatalog();if(page==='workshop')await loadExpansions();
    toast(durabilityNotice||(isLive()?'Farm saved. Return to the farm to see your changes.':'A little magic, safely saved. Snapshot created.'));
    if(preview.gift)showModal(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="gift-reveal-heading"><header class="modal-head"><div><div class="eyebrow">A little piece of the old farm</div><h2 id="gift-reveal-heading">A gift, ready for you.</h2></div><button class="close" data-action="close-modal" aria-label="Close gift">×</button></header><div class="modal-body">${giftCard(preview.gift)}<p class="helper-line">Saved in ${preview.gift.group==='storage'?'home storage':'your Gift Box'}. ${isLive()?'Return to the farm to place it.':'Export this copy to bring the gift into the game.'}</p>${durabilityNotice?`<p role="alert">${esc(durabilityNotice)}</p>`:''}</div><footer class="modal-footer">${actionButton('Lovely, thank you','close-modal','primary')}</footer></section>`);
  }catch(error){closeModal();errorToast(error);}finally{busy=false;}
}
function itemStatTiles(item){
  const facts={...item,...item.encyclopedia?.facts},tiles=[],growth=Number(facts.growTime)*(state?.rules?.inGameDaySeconds||82800)*(state?.rules?.growMultiplier||1);
  if(growth>0)tiles.push([img('seed'),growth<3600?Math.ceil(growth/60)+' min':Number((growth/3600).toFixed(1))+' hours',item.type==='seed'?'Grows in':['animal','tree'].includes(item.type)?'Harvest every':'Ready in']);
  if(Number(facts.coinYield)>0)tiles.push([img('scythe'),currencyAmount(facts.coinYield,'coins'),'Harvest']);
  if(Number(facts.requiredLevel)>0)tiles.push([img('xp-star'),esc('Level '+number(facts.requiredLevel)),'Unlocks at']);
  if(Number(facts.harvestXp)>0)tiles.push([img('xp'),esc(number(facts.harvestXp)+' XP'),'Harvest bonus']);
  return tiles.length?`<div class="item-stat-tiles">${tiles.slice(0,3).map(([icon,value,label])=>`<div>${icon}<span>${label}</span><b>${value}</b></div>`).join('')}</div>`:'';
}
