function sourceLinks(sources){return (Array.isArray(sources)?sources:[]).map(source=>{let url;try{url=new URL(source.url);}catch{}return url&&['http:','https:'].includes(url.protocol)?`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(source.title||'Historical source')} ↗</a>`:`<span>${esc(source.title||'Archive source')}</span>`;}).join(' · ');}
function historyFilters(){const filters=catalog.historyFilters||{};return `<div class="history-filters"><label>Recorded year<select class="select" id="history-year"><option value="">All recorded years</option>${(filters.years||[]).map(year=>`<option value="${esc(year)}" ${historyYear===year?'selected':''}>${esc(year)}</option>`).join('')}</select></label><label>How it was found<select class="select" id="history-acquisition"><option value="">All acquisition methods</option>${(filters.acquisitions||[]).map(method=>`<option value="${esc(method)}" ${historyAcquisition===method?'selected':''}>${esc(method)}</option>`).join('')}</select></label></div>`;}
