function archiveMarket(){const collections=catalog.collections||[],active=collections.find(c=>c.id===catalogCollection);return `<section class="panel archive-intro"><div class="panel-body"><div class="eyebrow">The archive is always open</div><h2>Every corner of the archive.</h2><p>Start with the full recovered catalog or explore a historical collection. Supported items can become gifts without a deadline.</p><div class="collection-shelves"><button class="collection-shelf ${catalogCollection?'':'active'}" data-collection="" aria-pressed="${!catalogCollection}"><b>All recovered items</b><small>Every category · no collection filter</small></button>${collections.map(c=>`<button class="collection-shelf ${c.id===catalogCollection?'active':''}" data-collection="${esc(c.id)}" aria-pressed="${c.id===catalogCollection}"><b>${esc(c.name)}</b><small>${esc(c.releaseDate||c.kind||'Archive collection')}${Array.isArray(c.items)?' · '+number(c.items.length)+' records':''}</small></button>`).join('')}</div>${active?`<div class="shelf-note"><b>${esc(active.kind||'Historical collection')}</b><p>${esc(active.description||active.note||'')}</p>${active.unmatchedItems?.length?`<p class="small">${number(active.unmatchedItems.length)} historical prizes are still being identified.</p>`:''}${active.sources?.length?`<p class="small">${sourceLinks(active.sources)}</p>`:''}<p class="helper-line">A prize shelf records historical contents. No random odds or original event mechanics are invented.</p></div>`:''}</div></section>${market()}`;}
function helperKind(){return page==='collections'||(page==='collectibles'&&collectibleView==='collection')?'collection':page==='quests'?'quest':null;}
function isProgressionPage(){return page==='progression'||(page==='collectibles'&&collectibleView!=='collection');}
