async function selectCollectibleView(next){if(!['collection','mastery','ribbon'].includes(next))return;if(collectibleView!=='collection')collectibleTrackFilters[collectibleView]={query:progressionQuery,status:progressionStatus,page:progressionPageNumber};collectibleView=next;page='collectibles';if(next==='collection'){render();await loadHelpers('collection');}else{const filter=collectibleTrackFilters[next];progressionKind=next;progressionQuery=filter.query;progressionStatus=filter.status;progressionPageNumber=filter.page;progressionData={items:[],totals:{},loading:true};render();await loadProgression();}}
function recoveredArt(record,cls='',alt=''){const source=record?.artwork?.status==='missing'?null:record?.image||record?.icon;return source&&source!=='none'?`<img class="${esc(cls)}" src="${itemImage({image:source})}" alt="${esc(alt)}" loading="lazy">`:`<span class="art-unavailable ${esc(cls)}" aria-label="Picture unavailable">Picture unavailable</span>`;}
